<?php
namespace App\Http\Controllers\Api\V1\Guest;
use App\Http\Controllers\Controller; use App\Models\Reservation; use App\Services\Reservations\AvailabilityService; use Carbon\Carbon; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class GuestBookingChangeController extends Controller{private function own(Request $r,Reservation $x){abort_unless($r->user()->role==='guest'&&$r->user()->guest_id===$x->guest_id,403);abort_if(in_array((string)$x->status->value,['checked_in','checked_out','cancelled'],true),422,'Booking can no longer be changed.');}
 public function cancel(Request $r,Reservation $x){$this->own($r,$x);$d=$r->validate(['reason'=>'required|string|max:1000']);$x->update(['status'=>'cancelled','cancelled_at'=>now(),'cancellation_reason'=>$d['reason']]);return ['message'=>'Booking cancelled. Refunds, where applicable, remain subject to the hotel cancellation policy.','reservation'=>$x->fresh()];}
 public function reschedule(Request $r,Reservation $x,AvailabilityService $a){$this->own($r,$x);$d=$r->validate(['check_in'=>'required|date|after_or_equal:today','check_out'=>'required|date|after:check_in']);$in=Carbon::parse($d['check_in'])->setTime(14,0);$out=Carbon::parse($d['check_out'])->setTime(11,0);$roomId=$x->rooms()->value('room_id');$available=$a->availableRoomIds($x->property_id,$in,$out,$x->id);if(!in_array($roomId,$available,true))throw ValidationException::withMessages(['check_in'=>'The allocated room is unavailable for those dates.']);$nights=max(1,$in->copy()->startOfDay()->diffInDays($out->copy()->startOfDay()));$rr=$x->rooms()->first();DB::transaction(function()use($x,$in,$out,$nights,$rr){$base=(float)$rr->nightly_rate*$nights;$x->update(['check_in_at'=>$in,'check_out_at'=>$out,'subtotal'=>$base,'grand_total'=>$base+(float)$x->tax_total-(float)$x->discount_total,'deposit_required'=>min((float)$x->deposit_required,$base),'reschedule_count'=>$x->reschedule_count+1]);$rr->update(['check_in_at'=>$in,'check_out_at'=>$out,'nights'=>$nights,'line_total'=>$base]);});return $x->fresh()->load('rooms.room');}}
